import { createServerOnlyFn } from "@tanstack/react-start";
import {
  createStartHandler,
  defaultStreamHandler,
} from "@tanstack/react-start/server";
import {
  CalculatorRequestBodyPolicy,
  withCalculatorRequestBodyLimit,
} from "@taxkit/api-http/request-boundary";
import { applyCachePolicy } from "@taxkit/api-http/response-policy";
import { CalculatorRequestRateKey } from "@taxkit/calculators/admission.service";
import { DocsDiscoveryPath } from "@taxkit/content/schemas";
import { AuAnnualTaxCalculatorId } from "@taxkit/rules-au-income-tax/schemas";
import { AuPayCalculatorId } from "@taxkit/rules-au-pay/schemas";
import { calculatorEdgeRateKey } from "api/edge-identity";
import { Effect, ErrorReporter, Match, Schema } from "effect";
import {
  Headers as EffectHeaders,
  HttpServerError,
  HttpServerRequest,
  HttpServerResponse,
} from "effect/http";

import { WebsiteAnalyticsRelay } from "./lib/analytics/relay/service";
import { WebsiteHost } from "./lib/api/host.server";
import { calculate } from "./lib/api/requests";
import { withDocsRepresentation } from "./lib/docs/markdown.response.server";
import {
  takeHomeRequestFromForm,
  annualTaxRequestFromForm,
  AnnualTaxForm,
  TakeHomeForm,
  WebsiteInputError,
} from "./lib/form.boundary";
import type { WebsiteCalculatorForm } from "./lib/form.boundary";
import { runtime } from "./lib/runtime.server";
import { WebsiteSubmission, WebsiteSubmissionTransport } from "./lib/schemas";
import type { WebsiteServerRenderContext } from "./lib/schemas";

const render = createStartHandler<{
  server: { requestContext: WebsiteServerRenderContext };
}>(defaultStreamHandler);

// The Worker entry is server-only; the runtime never reaches a browser bundle.
const handleRequest = createServerOnlyFn((request: Request) =>
  // A standard HTML form remains usable without JavaScript. Its checked
  // request reaches the same named RPC client through the private binding.
  // Only plain, Schema-encoded form/report data reaches TanStack rendering.
  runtime.runPromise(
    Effect.gen(function* websiteRequest() {
      const url = new URL(request.url);
      if (url.pathname.startsWith("/ingest/")) {
        const relay = yield* WebsiteAnalyticsRelay;
        const incoming = yield* HttpServerRequest.HttpServerRequest;
        return yield* relay.handle(incoming).pipe(
          Effect.catchTag("WebsiteRelayFailure", (error) =>
            Effect.succeed(
              HttpServerResponse.empty({
                headers: { "cache-control": "no-store" },
                status: Match.value(error.reason).pipe(
                  Match.when("configuration", () => 503),
                  Match.when("origin", () => 403),
                  Match.whenOr("metadata", "request", () => 400),
                  Match.when("request-size", () => 413),
                  Match.whenOr(
                    "transport",
                    "redirect",
                    "response-size",
                    () => 502
                  ),
                  Match.when("deadline", () => 504),
                  Match.exhaustive
                ),
              })
            )
          )
        );
      }
      const discoveryPath = url.pathname;
      if (Schema.is(DocsDiscoveryPath)(discoveryPath)) {
        if (request.method !== "GET" && request.method !== "HEAD") {
          return HttpServerResponse.empty({
            headers: { allow: "GET, HEAD" },
            status: 405,
          });
        }
        if (url.search !== "") {
          return HttpServerResponse.empty({ status: 400 });
        }
        // The API owns the finished document; forward it once.
        const host = yield* WebsiteHost;
        return yield* host
          .forward(`/api/v1/docs/discovery${discoveryPath}`)
          .pipe(
            Effect.map(HttpServerResponse.fromWeb),
            Effect.catch(() =>
              Effect.succeed(HttpServerResponse.empty({ status: 503 }))
            )
          );
      }
      // The framework still mounts its server-function base. The Website
      // declares no server functions, so every such address is absent.
      if (
        url.pathname === "/_serverFn" ||
        url.pathname.startsWith("/_serverFn/")
      ) {
        return HttpServerResponse.empty({ status: 404 });
      }
      const calculatorId = Match.value(url.pathname).pipe(
        Match.when("/calculators/au.income-tax.annual", () =>
          AuAnnualTaxCalculatorId.make("au.income-tax.annual")
        ),
        Match.when("/calculators/au.pay.withholdings", () =>
          AuPayCalculatorId.make("au.pay.withholdings")
        ),
        Match.when("/", () => AuPayCalculatorId.make("au.pay.take-home")),
        Match.orElse(() => null)
      );
      return yield* request.method !== "POST" || calculatorId === null
        ? Effect.gen(function* websiteHtml() {
            const incoming = yield* HttpServerRequest.HttpServerRequest;
            const htmlRequest = yield* HttpServerRequest.toWeb(incoming).pipe(
              Effect.orDie
            );
            return yield* Effect.promise(() =>
              Promise.resolve(render(htmlRequest, { context: {} }))
            ).pipe(Effect.map(HttpServerResponse.fromWeb));
          }).pipe(withDocsRepresentation)
        : withCalculatorRequestBodyLimit(
            Effect.gen(function* () {
              const incoming = yield* HttpServerRequest.HttpServerRequest;
              const bounded = yield* HttpServerRequest.toWeb(incoming, {
                signal: request.signal,
              });
              const data = yield* Effect.tryPromise({
                catch: () =>
                  new WebsiteInputError({
                    message: "Enter a valid pay amount and pay period.",
                  }),
                try: () => bounded.formData(),
              });
              const decodedForm: Effect.Effect<
                WebsiteCalculatorForm,
                Schema.SchemaError
              > =
                calculatorId === "au.income-tax.annual"
                  ? Schema.decodeUnknownEffect(AnnualTaxForm)({
                      taxableDollars: data.get("taxableDollars"),
                    })
                  : Schema.decodeUnknownEffect(TakeHomeForm)({
                      grossDollars: data.get("grossDollars"),
                      period: data.get("period"),
                      taxFreeThresholdClaimed:
                        data.get("taxFreeThresholdClaimed") === "on",
                    });
              const form = yield* decodedForm.pipe(
                Effect.mapError(
                  () =>
                    new WebsiteInputError({
                      message: "Enter a valid pay amount and pay period.",
                    })
                )
              );
              const result = yield* (
                Schema.is(AnnualTaxForm)(form)
                  ? annualTaxRequestFromForm(form)
                  : takeHomeRequestFromForm(
                      form,
                      AuPayCalculatorId.make(
                        calculatorId === "au.pay.withholdings"
                          ? "au.pay.withholdings"
                          : "au.pay.take-home"
                      )
                    )
              ).pipe(
                Effect.fromResult,
                Effect.flatMap((input) =>
                  WebsiteHost.pipe(
                    Effect.flatMap((host) => Effect.fromResult(host.client)),
                    Effect.flatMap((client) => calculate(client, input))
                  )
                ),
                Effect.result
              );
              const submission = yield* Schema.encodeEffect(
                WebsiteSubmissionTransport
              )(WebsiteSubmission.make({ calculatorId, form, result })).pipe(
                Effect.orDie
              );
              const headers = new Headers(request.headers);
              headers.delete("content-length");
              headers.delete("content-type");
              const response = yield* Effect.promise(() =>
                Promise.resolve(
                  render(
                    new Request(request.url, {
                      headers,
                      method: "GET",
                      signal: request.signal,
                    }),
                    { context: { submission } }
                  )
                )
              );
              return HttpServerResponse.fromWeb(response);
            }),
            CalculatorRequestBodyPolicy.make({ responseFormat: "html" })
          ).pipe(
            Effect.catchTag("WebsiteInputError", () =>
              Effect.succeed(HttpServerResponse.empty({ status: 400 }))
            )
          );
    }).pipe(
      // Native HTTP failure matching preserves aborts and safe empty errors.
      // The installed host reporter discards arbitrary Causes before logging.
      Effect.catchCause((cause) =>
        HttpServerError.causeResponse(cause).pipe(
          Effect.flatMap(([response, reportable]) =>
            ErrorReporter.report(reportable).pipe(Effect.as(response))
          )
        )
      ),
      // One cache decision for every reply. Public pages, Markdown and
      // discovery documents are shared; submissions, errors, analytics and
      // anything setting a cookie are not.
      Effect.map((response) =>
        applyCachePolicy(response, {
          method: request.method,
          publicRead: !new URL(request.url).pathname.startsWith("/ingest/"),
        })
      ),
      Effect.provideService(
        CalculatorRequestRateKey,
        calculatorEdgeRateKey(EffectHeaders.fromInput(request.headers))
      ),
      Effect.provideService(
        HttpServerRequest.HttpServerRequest,
        HttpServerRequest.fromWeb(request)
      ),
      Effect.scoped,
      Effect.map(HttpServerResponse.toWeb)
    ),
    { signal: request.signal }
  )
);

export default { fetch: handleRequest };
import {
  RegistryContext,
  RegistryProvider,
  scheduleTask,
  useAtomInitialValues,
} from "@effect/atom-react";
import {
  createRootRouteWithContext,
  HeadContent,
  Link,
  Outlet,
  Scripts,
} from "@tanstack/react-router";
import type { CalculatorCatalogResponse } from "@taxkit/calculators/schemas";
import { Array, Function, Option, Result, Schema } from "effect";
import type * as AtomRegistry from "effect/reactivity/AtomRegistry";
import { createContext, useEffect, useMemo, useRef } from "react";
import type { ReactNode } from "react";

import { publicSettingsAtom } from "#/lib/api/client.atoms";
import type { LoaderContext } from "#/lib/loader-context";
import { loadRoot } from "#/lib/loaders";
import { WebsiteRootView, WebsiteSubmissionTransport } from "#/lib/schemas";
import type { WebsitePublicSettings, WebsiteSubmission } from "#/lib/schemas";

import "../styles.css";

// Only the root route restores these values. Children receive checked values.
export const WebsiteSubmissionContext = createContext<
  Option.Option<typeof WebsiteSubmission.Type>
>(Option.none());
export const WebsiteCatalogueContext = createContext<
  Option.Option<typeof CalculatorCatalogResponse.Type>
>(Option.none());

const SettingsUnavailable = () => (
  <main className="home">
    <h1>TaxKit</h1>
    <p role="alert">TaxKit cannot load its settings. Please try again later.</p>
  </main>
);

const RootShell = ({ children }: { readonly children: ReactNode }) => (
  <html lang="en-AU">
    <head>
      <HeadContent />
    </head>
    <body>
      {children}
      <Scripts />
    </body>
  </html>
);

// The browser registry was created before loaders ran; React uses that same
// registry. React can replay mount and cleanup in development, so disposal is
// scheduled and cancelled by the next mount rather than run immediately.
const BrowserRegistry = ({
  children,
  registry,
}: Readonly<{ children: ReactNode; registry: AtomRegistry.AtomRegistry }>) => {
  const pendingDisposal = useRef(Function.constVoid);
  useEffect(() => {
    pendingDisposal.current();
    return () => {
      pendingDisposal.current = scheduleTask(() => {
        registry.dispose();
      });
    };
  }, [registry]);
  return (
    <RegistryContext.Provider value={registry}>
      {children}
    </RegistryContext.Provider>
  );
};

const RootRegistry = ({
  children,
  registry,
}: Readonly<{ children: ReactNode; registry: LoaderContext["registry"] }>) =>
  Option.match(registry, {
    // Server rendering keeps an isolated registry per request.
    onNone: () => <RegistryProvider>{children}</RegistryProvider>,
    onSome: (value) => (
      <BrowserRegistry registry={value}>{children}</BrowserRegistry>
    ),
  });

const InitialSettings = ({
  children,
  settings,
}: Readonly<{ children: ReactNode; settings: WebsitePublicSettings }>) => {
  useAtomInitialValues([[publicSettingsAtom, Option.some(settings)]]);
  return children;
};

export const Route = createRootRouteWithContext<LoaderContext>()({
  component: function RootComponent() {
    const data = Route.useLoaderData();
    const { registry } = Route.useRouteContext();
    const view = useMemo(
      () => Schema.decodeUnknownResult(WebsiteRootView)(data.view),
      [data.view]
    );
    const submission = useMemo(
      () =>
        Option.fromNullishOr(data.submission).pipe(
          Option.flatMap((encoded) =>
            Schema.decodeResult(WebsiteSubmissionTransport)(encoded).pipe(
              Result.getSuccess
            )
          )
        ),
      [data.submission]
    );
    if (Result.isFailure(view)) {
      return <SettingsUnavailable />;
    }
    const { catalogue, settings } = view.success;
    return (
      <RootRegistry registry={registry}>
        <InitialSettings settings={settings}>
          <WebsiteSubmissionContext.Provider value={submission}>
            <WebsiteCatalogueContext.Provider value={catalogue}>
              <div className="app-shell">
                <a className="skip-link" href="#main-content">
                  Skip to content
                </a>
                <nav aria-label="Calculators">
                  {Option.match(catalogue, {
                    onNone: () => (
                      <p>
                        The calculator list could not load. Please reload this
                        page.
                      </p>
                    ),
                    onSome: (value) => (
                      <ul>
                        {Array.map(value.calculators, (calculator) => (
                          <li key={calculator.calculatorId}>
                            {calculator.calculatorId === "au.pay.take-home" ? (
                              <Link
                                activeProps={{ "aria-current": "page" }}
                                to="/"
                              >
                                {calculator.title}
                              </Link>
                            ) : (
                              <Link
                                activeProps={{ "aria-current": "page" }}
                                to="/calculators/$calculatorId"
                                params={{
      66 routes/$.tsx
     210 routes/__root.tsx
     101 routes/agents.tsx
      91 routes/calculators.$calculatorId.tsx
      13 routes/index.tsx
      77 routes/search.tsx
     308 lib/schemas.ts
     214 lib/calculator.atoms.ts
     183 lib/browser-tools.atoms.ts
    1263 total

import type {
  CalculatorRunResponse,
  CalculatorRunServiceRequest,
} from "@taxkit/calculators/schemas";
import { AnnualTaxReport } from "@taxkit/rules-au-income-tax/schemas";
import {
  AuPayCalculatorId,
  PayWithholdingsLedger,
  TakeHomePayReport,
} from "@taxkit/rules-au-pay/schemas";
import { Cause, Effect, Match, Option, Result, Schema } from "effect";
import * as AsyncResult from "effect/reactivity/AsyncResult";
import * as Atom from "effect/reactivity/Atom";

import { ApiClient, apiClientRuntime } from "./api/client.atoms";
import type { WebsiteCalculationFailure } from "./api/errors";
import { calculate } from "./api/requests";
import { calculationFailureMessage } from "./calculation-failure";
import {
  takeHomeRequestFromForm,
  annualTaxRequestFromForm,
  initialTakeHomeForm,
  AnnualTaxForm,
  WebsiteInputError,
  TakeHomeForm,
} from "./form.boundary";
import type { WebsiteCalculatorForm } from "./form.boundary";
import type { WebsiteCalculatorViewState } from "./schemas";

// The registry owns separate temporary state for each checked calculator ID.
// The family memoises descriptions, never a client or a computed answer.
export const calculatorPageAtoms = Atom.family(
  (calculatorId: CalculatorRunServiceRequest["calculatorId"]) => {
    const form = Atom.make<WebsiteCalculatorForm>(
      Match.value(calculatorId).pipe(
        Match.when("au.income-tax.annual", () =>
          AnnualTaxForm.make({ taxableDollars: "67000" })
        ),
        Match.when("au.pay.take-home", () => initialTakeHomeForm),
        Match.orElse(() => ({
          grossDollars: "9500",
          period: "monthly",
          taxFreeThresholdClaimed: false,
        }))
      )
    );
    // The native client's calculation, with this feature's deadline, reply
    // bound and calculator/report correlation. Replacing the request or
    // interrupting it cancels the browser call.
    const calculation = apiClientRuntime.fn<CalculatorRunServiceRequest>()(
      (request) =>
        ApiClient.pipe(Effect.flatMap((client) => calculate(client, request)))
    );
    const showSaved = Atom.make(true);
    const showCalculation = Atom.make(false);
    const formError = Atom.make(Option.none<string>());
    const savedReport = Atom.make(
      Option.none<CalculatorRunResponse["report"]>()
    );
    const savedMessage = Atom.make(Option.none<string>());
    // Checked request identity belongs to one visible attempt. An edit or a
    // newer manual/tool submission invalidates a waiter for the older attempt.
    const attempt = Atom.make(Option.none<CalculatorRunServiceRequest>());
    const cancel = Atom.fnSync<"cancel">()((_, get) => {
      get.set(attempt, Option.none());
      get.set(calculation, Atom.Interrupt);
      get.set(showCalculation, false);
    });
    const edit = Atom.fnSync<WebsiteCalculatorForm>()((value, get) => {
      get.set(attempt, Option.none());
      get.set(calculation, Atom.Interrupt);
      get.set(showCalculation, false);
      get.set(showSaved, false);
      get.set(formError, Option.none());
      get.set(form, value);
    });
    const submit = Atom.fnSync<"calculate">()((_, get) => {
      const current = get(form);
      const request = Result.gen(function* () {
        if (calculatorId === "au.income-tax.annual") {
          return yield* "taxableDollars" in current
            ? annualTaxRequestFromForm(current)
            : Result.fail(
                new WebsiteInputError({
                  message: "Enter a valid annual taxable income.",
                })
              );
        }
        return yield* "grossDollars" in current
          ? takeHomeRequestFromForm(
              current,
              AuPayCalculatorId.make(calculatorId)
            )
          : Result.fail(
              new WebsiteInputError({
                message: "Enter a valid pay amount and pay period.",
              })
            );
      });
      get.set(showCalculation, true);
      get.set(showSaved, false);
      if (Result.isFailure(request)) {
        get.set(attempt, Option.none());
        get.set(calculation, Atom.Interrupt);
        get.set(formError, Option.some(request.failure.message));
        return;
      }
      get.set(formError, Option.none());
      get.set(attempt, Option.some(request.success));
      get.set(calculation, request.success);
    });
    const group = {
      attempt,
      calculation,
      cancel,
      edit,
      form,
      formError,
      savedMessage,
      savedReport,
      showCalculation,
      showSaved,
      submit,
      // The registry retains this in-memory page snapshot across an uncommitted
      // React render. Otherwise idle cleanup can erase once-seeded SSR values
      // before hydration subscribes. Page cleanup still interrupts live work.
      // The retained view also holds its whole weak-family description group.
      // Otherwise browser GC can replace that group on a return visit while the
      // old values remain in the registry. The callback runs after group creation.
      // Disposing the root registry releases the snapshot and its client.
      view: Atom.make((get): WebsiteCalculatorViewState => {
        const current = get(calculation);
        const submitted = get(showCalculation);
        const saved = get(showSaved);
        const inputError = get(formError);
        const report = AsyncResult.value(current).pipe(
          Option.filter(
            (value) => value.calculator.calculatorId === calculatorId
          ),
          Option.map((value) => value.report),
          Option.orElse(() => get(savedReport)),
          Option.filter((value) =>
            Match.value(calculatorId).pipe(
              Match.when("au.income-tax.annual", () =>
                Schema.is(AnnualTaxReport)(value)
              ),
              Match.when("au.pay.take-home", () =>
                Schema.is(TakeHomePayReport)(value)
              ),
              Match.orElse(() => Schema.is(PayWithholdingsLedger)(value))
            )
          )
        );
        const message = Option.match(inputError, {
          onNone: () => {
            if (
              submitted &&
              !current.waiting &&
              (AsyncResult.isFailure(current) ||
                (AsyncResult.isSuccess(current) && Option.isNone(report)))
            ) {
              if (AsyncResult.isFailure(current)) {
                return current.cause.pipe(
                  Cause.findErrorOption,
                  Option.map(calculationFailureMessage)
                );
              }
              return Option.some(
                "The calculation could not finish. Please try again."
              );
            }
            return saved ? get(savedMessage) : Option.none<string>();
          },
          onSome: Option.some,
        });
        return {
          busy: submitted && current.waiting,
          calculatorId,
          form: get(group.form),
          message,
          report,
          stale:
            Option.isSome(report) &&
            !saved &&
            (!submitted ||
              current.waiting ||
              !AsyncResult.isSuccess(current) ||
              Option.isSome(inputError)),
        };
      }).pipe(Atom.keepAlive),
    } as const;
    return group;
  }
);

// Home uses the same page commands and state owner as the other calculators.
// These existing names retain their narrow React/test call sites.
const home = calculatorPageAtoms(AuPayCalculatorId.make("au.pay.take-home"));
export const calculateAtom: Atom.AtomResultFn<
  CalculatorRunServiceRequest,
  CalculatorRunResponse,
  WebsiteCalculationFailure
> = home.calculation;
export const takeHomeFormAtom = Atom.writable(
  (get) => {
    const form = get(home.form);
    return Schema.is(TakeHomeForm)(form) ? form : initialTakeHomeForm;
  },
  (get, form: TakeHomeForm) => get.set(home.form, form)
);
export const submitTakeHomeAtom = home.submit;
export const editTakeHomeAtom = Atom.fnSync<TakeHomeForm>()((value, get) =>
  get.set(home.edit, value)
);
import type { CalculatorRunServiceRequest } from "@taxkit/calculators/schemas";
import { Duration, Effect, Option, Result, Schema, Stream } from "effect";
import * as Atom from "effect/reactivity/Atom";
import * as AtomRegistry from "effect/reactivity/AtomRegistry";

import {
  ApiClient,
  apiClientRuntime,
  publicSettingsAtom,
} from "./api/client.atoms";
import { readCatalogue } from "./api/requests";
import { registerWebsiteBrowserTools } from "./browser-tools.boundary";
import { WebsiteBrowserToolFailure } from "./browser-tools.schemas";
import { WebsiteBrowserToolkit } from "./browser-tools.toolkit";
import { calculatorPageAtoms } from "./calculator.atoms";
import { AnnualTaxForm, TakeHomeForm } from "./form.boundary";

// One mounted calculator owns these registrations and callbacks through its
// existing React runtime. Handlers invoke its existing edit/submit commands;
// they neither acquire another client nor perform their own calculation.
export const browserCalculatorToolsAtom = Atom.family(
  (calculatorId: CalculatorRunServiceRequest["calculatorId"]) => {
    const page = calculatorPageAtoms(calculatorId);
    return apiClientRuntime.fn<"register">()((_, get) =>
      Effect.gen(function* () {
        const settings = get.registry.get(publicSettingsAtom);
        if (Option.isNone(settings)) {
          return;
        }
        // Reads made by a later native callback do not retain an idle atom.
        // Hold the current attempt for this page's entire registration lifetime.
        get.mount(page.attempt);
        const client = yield* ApiClient;
        const handlers = yield* WebsiteBrowserToolkit.toHandlers({
          taxkit_calculate_visible_form: Effect.fn(
            "WebsiteBrowserTools.calculateVisibleForm"
          )(() =>
            Effect.gen(function* () {
              // Admission and visible submission are one synchronous registry
              // command. Two tool calls cannot both claim the same idle form.
              const owned = yield* Effect.sync(() => {
                if (get.registry.get(page.view).busy) {
                  return Result.fail(
                    new WebsiteBrowserToolFailure({
                      code: "calculation-busy",
                      retry: "wait-then-try-manually",
                    })
                  );
                }
                get.set(page.submit, "calculate");
                return get.registry.get(page.attempt).pipe(
                  Option.match({
                    onNone: () =>
                      Result.fail(
                        new WebsiteBrowserToolFailure({
                          code: "invalid-input",
                          retry: "check-the-visible-form",
                        })
                      ),
